import{z as o,x as s,o as B,c as p,q as A,j as t,D as a,d as r,s as n,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"图像预处理的批处理","description":"","frontmatter":{"title":"图像预处理的批处理","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mm-image-preprocess-batching.md","filePath":"llm/mm-image-preprocess-batching.md","lastUpdated":1791063341000}'),m={name:"llm/mm-image-preprocess-batching.md"};function d(C,E,D,P,h,c){const i=s("Mermaid");return B(),p("div",null,[E[2]||(E[2]=A('<h1 id="图像预处理的批处理" tabindex="-1">图像预处理的批处理 <a class="header-anchor" href="#图像预处理的批处理" aria-label="Permalink to &quot;图像预处理的批处理&quot;">​</a></h1><div class="epigraph"><p>GPU 一步几十毫秒，CPU 解一张手机照片几十毫秒；多模态服务最长的队，常常排在没有 GPU 的那一段。</p><footer>—— 据 HuggingFace 图像处理器与 vLLM 多模态输入管线的实现口径整理</footer></div><p><a href="/llm/mm-serving-vision-encoder">上一课</a>把编码器立成独立服务组件：分辨率桶解决形状动态，嵌入缓存省掉重复编码。但桶的档位是谁定的、图像进编码器之前经历了什么，还悬着。JPEG/HEIF 解码、EXIF 方向、缩放、归一化、切 patch 全在 CPU 上，预处理是编码批处理的真正上游。本课写这段 CPU 流水怎么组织成批：worker 池、变长批的组装、主机到显卡的搬运，以及 CPU 跟不上时 GPU 饿死的样子。token 数怎么算留到下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一张图像从上传到能进 ViT，要过五道：字节流解码成位图；按 EXIF 转正——手机照片常带旋转标记，跳过这步模型看到的就是横躺的图；按目标档位缩放；减均值除方差地归一化；切 patch 排成序列。每道都是纯 CPU 操作，单张几十毫秒量级，且与请求的关键路径串行：预处理不结束，编码器无事可做。GPU 一秒能编几十张图，单线程 CPU 一秒只能预处理几十张，看似匹配，实则一个抖动就错位——批越大，需要的预处理越集中，CPU 峰值压力随批大小一起涨。</p><p>变长是第二重麻烦。<a href="/llm/qwen-vl-naive-dynamic-res">原生动态分辨率</a>意味着同一批请求里的图宽高各异、patch 数各异，批内张量要对齐就得 padding 到最大形状。一个 224×224 缩略图和一张 1344×896 文档页同批，前者陪跑后者的计算与显存，浪费由批内方差决定。</p><p><span class="marginnote">EXIF 术语翻译：手机竖拍时，传感器存下的画面其实是横的，只在文件的 EXIF 元数据里记一个「请旋转 90°」的标记，相册软件看标记再帮你转正。跳过这一步，模型吃到的就是横躺的照片——人眼看没问题（软件转过了），模型直读字节就出问题。这是多模态服务「离线测试好好的、上线效果怪」的经典来源之一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>组织方式是把预处理做成<strong>独立 worker 池</strong>：解码、缩放、归一化在各 worker 上并行，产物进入按分辨率档分的队列；编码器池从队列取整批。这与<a href="/llm/mm-serving-vision-encoder">上一课</a>的桶是同一套档位表——预处理按表把图缩到档，编码器按表组批，两张表必须同源，否则桶对不齐。请求到达即开始预处理，不等上一批编码结束，CPU 与 GPU 由此错峰。</p><p>搬运要过两道优化。解码产物是页锁定内存（pinned memory），主机到显卡的异步拷贝才能与下一次解码重叠；归一化能挪到 GPU 就挪——缩放留在 CPU（插值质量可控），归一化放进编码前向的第一层，省一半 CPU 与一次全量内存写。同一请求带多张图时，把它们的 patch 拼进同一个编码批，一次前向出全部嵌入，省掉多次小批的启动开销。</p><p><span class="marginnote">一张 3840×2160 的图解码成 RGB 是约 24 MB，是压缩文件的几十倍；批 32 张就有约 0.8 GB 内存要解码、缩放、再拷走。预处理的成本大头是内存带宽，不是 CPU 的算术。</span></p>',11)),(B(),t(l,null,{default:a(()=>[n(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E9%87%8C%E7%9A%84%E5%9B%BE%E5%83%8F%E5%AD%97%E8%8A%82%22%5D%20--%3E%20DEC%5B%22worker%20%E6%B1%A0%E5%B9%B6%E8%A1%8C%E8%A7%A3%E7%A0%81%22%5D%0A%20%20DEC%20--%3E%20EXIF%7B%22EXIF%20%E6%97%8B%E8%BD%AC%E6%A0%87%E8%AE%B0%3F%22%7D%0A%20%20EXIF%20--%3E%7C%E6%9C%89%7C%20ROT%5B%22%E8%BD%AC%E6%AD%A3%22%5D%0A%20%20EXIF%20--%3E%7C%E6%97%A0%7C%20RES%0A%20%20ROT%20--%3E%20RES%5B%22%E6%8C%89%E6%A1%A3%E4%BD%8D%E8%A1%A8%E7%BC%A9%E6%94%BE%22%5D%0A%20%20RES%20--%3E%20Q%5B%22%E5%88%86%E6%A1%A3%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20PIN%5B%22%E9%A1%B5%E9%94%81%E5%AE%9A%E5%86%85%E5%AD%98%E7%BB%84%E8%A3%85%E6%88%90%E6%89%B9%22%5D%0A%20%20PIN%20--%3E%20H2D%5B%22%E5%BC%82%E6%AD%A5%E6%8B%B7%E5%85%A5%E6%98%BE%E5%8D%A1%22%5D%0A%20%20H2D%20--%3E%20ENC%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%E6%89%B9%E5%89%8D%E5%90%91%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"批组装的本质是用等待换效率：队列攒到同档 \\(B\\) 张或超时 \\(\\tau\\) 就发批。\\(B\\) 越大吞吐越高，但第 1 张图等了整整 \\(B-1\\) 张的预处理时间，首 token 延迟被队列拉长；\\(\\tau\\) 是这条折中的显式旋钮，超时发批保证低流量时段延迟有界。padding 浪费可写成 \\(\\sum_i (A_{\\max}-A_i)/A_{\\max}\\)，\\(A\\) 为 patch 数：档位表越细，批内 \\(A_{\\max}\\) 越贴近每张图，浪费越小，但批越小、调度越碎。档位数、批上限、超时三个参数要一起调，单拧一个都会把瓶颈搬到邻段。",-1)),E[5]||(E[5]=e("p",null,"CPU 容量是隐性上限。设单图预处理 \\(t_{\\mathrm{pp}}\\) 毫秒、worker 数 \\(W\\)，预处理吞吐就是 \\(W/t_{\\mathrm{pp}}\\) 张每秒；低于编码器吞吐时，GPU 利用率天花板被 CPU 钉死，加卡无效，加核才有效。诊断顺序是先看 GPU 利用率与预处理队列深度：队列持续非空说明 CPU 是瓶颈，队列常空而 GPU 不满才是编码器的问题。",-1)),(B(),t(l,null,{default:a(()=>[n(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARR%5B%22%E5%9B%BE%E5%83%8F%E8%AF%B7%E6%B1%82%E9%99%86%E7%BB%AD%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20Q%5B%22%E5%88%86%E6%A1%A3%E9%98%9F%E5%88%97%E6%94%92%E6%89%B9%22%5D%0A%20%20Q%20--%3E%20TRIG%7B%22%E6%94%92%E6%BB%A1%20B%20%E5%BC%A0%20%E6%88%96%20%E8%B6%85%E6%97%B6%20%CF%84%EF%BC%9F%22%7D%0A%20%20TRIG%20--%3E%7C%22%E6%BB%A1%20B%22%7C%20SEND%5B%22%E5%8F%91%E6%95%B4%E6%89%B9%EF%BC%9A%E5%90%9E%E5%90%90%E9%AB%98%22%5D%0A%20%20TRIG%20--%3E%7C%22%E5%88%B0%E6%97%B6%E6%9C%AA%E6%BB%A1%22%7C%20SEND2%5B%22%E6%8C%89%E7%8E%B0%E7%8A%B6%E5%8F%91%E6%89%B9%EF%BC%9A%E5%BB%B6%E8%BF%9F%E6%9C%89%E7%95%8C%22%5D%0A%20%20SEND%20--%3E%20PAD%5B%22%E6%89%B9%E5%86%85%E5%B7%AE%E8%B7%9D%E5%A4%A7%20%E2%86%92%20padding%20%E6%B5%AA%E8%B4%B9%E5%A4%9A%22%5D%0A%20%20SEND2%20--%3E%20LAT%5B%22%E5%B0%8F%E6%89%B9%E5%BF%AB%E8%B5%B0%20%E2%86%92%20%E9%A6%96%E5%9B%BE%E7%AD%89%E5%BE%97%E5%B0%91%22%5D%0A%20%20PAD%20--%3E%20TUNE%5B%22B%E3%80%81%CF%84%E3%80%81%E6%A1%A3%E4%BD%8D%E6%95%B0%E4%B8%89%E5%8F%82%E6%95%B0%E8%81%94%E5%8A%A8%E8%B0%83%22%5D%0A%20%20LAT%20--%3E%20TUNE%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p><span class="marginnote">padding 浪费的数字实例：224×224 的缩略图约 5 万像素，1344×896 的文档页约 120 万像素——同批对齐到后者时，缩略图只占约 4% 的位置，其余 96% 全是白算的空白。类比拼车：一辆 7 座车只坐了 1 位乘客也要跑全程，座位空驶率就是 padding 浪费率；分档队列相当于按目的地分区排车。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>预处理是<a href="/llm/mm-serving-vision-encoder">嵌入缓存</a>键的一部分，也是漂移的高发地：图像库升级换了缩放插值，或归一化常数改了精度，键没变缓存不失效，线上精度缓慢下滑且无从对账；预处理代码要进版本管理，版本号进键。EXIF 只在解码侧生效，训练数据若多数已转正，服务侧漏转正等于悄悄换分布。HEIF、动图、超大图的降采样策略各是独立分支，评测集里要各有样本，否则它们只在生产里第一次见。最后，批组装带来的排队让延迟方差变大，对延迟敏感的请求应允许插队小批，用吞吐换尾延迟。</p><p><span class="marginnote">常见误区：看到 GPU 利用率低就申请加卡。若瓶颈其实在 CPU 预处理（队列持续积压），新加的卡只会一起挨饿，钱花了速度不变。正确顺序是先看预处理队列深度——队列非空说明上游喂不上，加 worker 核才是对症药。这一步诊断错了，容量预算会整体买错方向。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预处理五道（解码、EXIF、缩放、归一化、切 patch）在 CPU，是编码批的真正上游与常见瓶颈。</li><li>独立 worker 池加分档队列，让 CPU 与 GPU 错峰；档位表必须与编码器分桶同源。</li><li>页锁定内存与异步拷贝让搬运重叠；归一化可上移进显卡。</li><li>批上限与超时是延迟-吞吐旋钮，padding 浪费由档内方差决定，三参数联动。</li><li>预处理进版本管理并写进缓存键，防止无声漂移；CPU 吞吐封顶时加卡无效。</li><li>出处：据 HuggingFace 图像处理器、vLLM 多模态输入管线实现与 Qwen-VL 动态分辨率叙述整理。</li></ul>',6))])}const U=o(m,[["render",d]]);export{F as __pageData,U as default};
